def save():(OUT/'artifact.json').write_text(json.dumps(d,indent=2)+'\n')
for v,p in BINS.items():
 r=subprocess.run([str(p),'--test'],cwd=OUT,env=ENV,capture_output=True,text=True,timeout=60);(OUT/(v+'-smoke.log')).write_text(r.stdout+r.stderr);d['validation'].append({'variant':v,'exit':r.returncode,'successful_cases':r.stdout.count('\nSuccess')});save();assert r.returncode==0,r.stderr[-3000:]
smoke=pathlib.Path('/tmp/ferroni-round2-profiles/smoke.log').read_text()
cases=[line.removeprefix('Testing ') for line in smoke.splitlines() if line.startswith('Testing ') and ('/rust/' in line or line.endswith('_rust')) and '/unicode_classes/' not in line and not line.startswith('Testing unicode_classes/') and not (line.startswith('Testing scanner_highlighting/') and '_compile_rust' not in line)]
shared=set(['general_regex/rust/'+n for n in ['email_validation','uuid_validation','number_validation','access_log_captures','url_extraction','unicode_words','email_redaction']]+['single_pattern/rust/literal_exact'])
d['case_order']=cases;d['shared_syntax_comparison_cases']=sorted(shared);d['order']='Within each case rotate baseline/candidate/C/regex then reverse for shared comparisons; otherwise ABBA/BAAB alternating. All runs retained.';save()
assert len(cases)==31, cases
for i,case in enumerate(cases):
 variants=['baseline','candidate','c','regex'] if case in shared else ['baseline','candidate']
 rotation=i%len(variants);forward=variants[rotation:]+variants[:rotation];order=forward+list(reversed(forward));counts={v:0 for v in variants};rows=[]
 for v in order:
  counts[v]+=1;label=f'confirmation-{v}-{counts[v]}';bench_id=case.replace('/rust/','/'+v+'/') if v in ['c','regex'] else case
  executable=BINS[v] if v in BINS else BINS['candidate'];cmd=[str(executable),'^'+re.escape(bench_id)+'$','--bench','--noplot','--save-baseline',label];start=time.monotonic()
  row={'case':case,'benchmark_id':bench_id,'variant':v,'label':label,'command':cmd,'start_utc':utc(),'load_average':os.getloadavg()};r=subprocess.run(cmd,cwd=OUT,env=ENV,capture_output=True,text=True,timeout=60);(OUT/f'{i}-{label}.log').write_text(r.stdout+r.stderr);row.update(exit=r.returncode,elapsed_seconds=time.monotonic()-start);assert r.returncode==0,r.stderr[-3000:]
  for k,f in [('estimates','estimates.json'),('samples','sample.json'),('benchmark','benchmark.json')]:row[k]=json.loads((OUT/'criterion'/bench_id/label/f).read_text())
  d['measurements'].append(row);rows.append(row);save()
 means={v:[r['estimates']['mean']['point_estimate'] for r in rows if r['variant']==v] for v in variants};avg={v:statistics.mean(vals) for v,vals in means.items()};s={'case':case,'run_means_ns':means,'average_ns':avg,'time_change_percent':(avg['candidate']/avg['baseline']-1)*100};d['summaries'].append(s);save();print(json.dumps(s),flush=True)
d['end_utc']=utc();save();print('COMPLETE',OUT,flush=True)

